ALTER TABLE public.conc_francesinha_entries ADD COLUMN IF NOT EXISTS matched_bank_id uuid REFERENCES public.conc_bank_entries(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS conc_francesinha_bank_idx ON public.conc_francesinha_entries(matched_bank_id);
CREATE OR REPLACE FUNCTION public.conc_boleto_movement_date(p_description text, p_credit_date date) RETURNS date LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $$ DECLARE m text[]; d date; BEGIN IF p_credit_date IS NULL THEN RETURN NULL; END IF; m:=regexp_match(coalesce(p_description,''),'([0-3][0-9])/([01][0-9])'); IF m IS NULL THEN RETURN p_credit_date; END IF; BEGIN d:=make_date(extract(year from p_credit_date)::int,m[2]::int,m[1]::int); IF d>p_credit_date THEN d:=make_date(extract(year from p_credit_date)::int-1,m[2]::int,m[1]::int); END IF; EXCEPTION WHEN datetime_field_overflow THEN RETURN NULL; END; RETURN d; END $$;
CREATE OR REPLACE FUNCTION public.conc_boleto_candidates(p_hotel text) RETURNS TABLE(bank_id uuid,movement_date date,credit_date date,total numeric,entry_ids uuid[],ar_ids uuid[],ready boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ WITH groups AS (SELECT f.data_movimento d,sum(f.valor_final) amount,array_agg(f.id) fids,array_agg(f.matched_ar_id) aids,bool_and(f.valor_final IS NOT NULL AND f.valor_final>0 AND a.id IS NOT NULL AND a.hotel_id=f.hotel_id AND round(a.amount,2)=round(f.valor_inicial,2) AND a.francesinha_status='liquidado') valid,count(*)=count(DISTINCT f.matched_ar_id) unique_invoices,bool_and(f.matched_bank_id IS NULL) unused FROM public.conc_francesinha_entries f LEFT JOIN public.ar_to_invoice_entries a ON a.id=f.matched_ar_id WHERE f.hotel_id=p_hotel AND f.acao='liquidacao' GROUP BY f.data_movimento), candidates AS (SELECT b.id,b.line_date,g.*,count(*) OVER(PARTITION BY g.d) n FROM groups g JOIN public.conc_bank_entries b ON b.hotel_id=p_hotel AND b.amount>0 AND upper(btrim(b.description)) ~ '^BOLETOS? RECEBIDOS?([[:space:]]|$)' AND public.conc_boleto_movement_date(b.description,b.line_date)=g.d AND b.line_date BETWEEN g.d AND g.d+5 AND round(b.amount,2)=round(g.amount,2)) SELECT id,d,line_date,amount,fids,aids,coalesce(valid AND unique_invoices AND unused AND n=1,false) FROM candidates $$;
REVOKE ALL ON FUNCTION public.conc_boleto_candidates(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.conc_boleto_candidates(text) TO service_role;
CREATE OR REPLACE FUNCTION public.conc_boleto_auto_match_impl(p_hotel text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r record; n int:=0; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('boleto:'||p_hotel,0)); WITH links AS (SELECT f.id,(array_agg(a.id))[1] ar_id FROM public.conc_francesinha_entries f JOIN public.ar_to_invoice_entries a ON a.hotel_id=f.hotel_id AND public.ar_doc_number(f.seu_numero) IN (public.ar_doc_number(a.boleto_number),public.ar_doc_number(a.nota_number)) AND round(a.amount,2)=round(f.valor_inicial,2) WHERE f.hotel_id=p_hotel AND f.acao='liquidacao' AND f.matched_ar_id IS NULL GROUP BY f.id HAVING count(*)=1) UPDATE public.conc_francesinha_entries f SET matched_ar_id=l.ar_id,result='aguardando_credito_bancario' FROM links l WHERE f.id=l.id; UPDATE public.ar_to_invoice_entries a SET francesinha_status='liquidado',francesinha_at=coalesce(a.francesinha_at,now()) WHERE a.hotel_id=p_hotel AND EXISTS(SELECT 1 FROM public.conc_francesinha_entries f WHERE f.hotel_id=p_hotel AND f.acao='liquidacao' AND f.matched_ar_id=a.id) AND a.francesinha_status IS DISTINCT FROM 'liquidado'; FOR r IN SELECT * FROM public.conc_boleto_candidates(p_hotel) WHERE ready LOOP PERFORM 1 FROM public.conc_bank_entries WHERE id=r.bank_id FOR UPDATE; UPDATE public.conc_francesinha_entries SET matched_bank_id=r.bank_id,result='baixa_dada' WHERE id=ANY(r.entry_ids); UPDATE public.ar_to_invoice_entries SET is_paid=true,gg_status='pago',paid_at=coalesce(paid_at,now()),paid_date=r.credit_date,paid_note=concat_ws(E'\n',nullif(paid_note,''),'Boleto validado no extrato em '||to_char(r.credit_date,'DD/MM/YYYY')) WHERE id=ANY(r.ar_ids) AND hotel_id=p_hotel AND (NOT coalesce(is_paid,false) OR paid_date IS NULL OR paid_note LIKE 'Francesinha: liquidação em %'); UPDATE public.conc_bank_entries SET matched_at=now() WHERE id=r.bank_id AND matched_at IS NULL; n:=n+1; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.conc_boleto_auto_match_impl(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.conc_boleto_auto_match_impl(text) TO service_role;
CREATE OR REPLACE FUNCTION public.conc_boleto_auto_match(p_hotel text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.can_access_conciliacao(auth.uid()) OR NOT public.can_view_hotel_data(auth.uid(),p_hotel) THEN RAISE EXCEPTION 'sem permissão'; END IF; RETURN public.conc_boleto_auto_match_impl(p_hotel); END $$;
REVOKE ALL ON FUNCTION public.conc_boleto_auto_match(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.conc_boleto_auto_match(text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.conc_auto_reconcile(_hotel_id text DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE n int; h record; BEGIN IF auth.uid() IS NULL OR NOT public.can_access_conciliacao(auth.uid()) THEN RAISE EXCEPTION 'not authorized'; END IF; IF _hotel_id IS NOT NULL AND NOT public.can_view_hotel_data(auth.uid(),_hotel_id) THEN RAISE EXCEPTION 'sem permissão'; END IF; n:=public.conc_auto_reconcile_impl(_hotel_id); FOR h IN SELECT DISTINCT hotel_id FROM public.conc_francesinha_entries WHERE (_hotel_id IS NULL OR hotel_id=_hotel_id) AND public.can_view_hotel_data(auth.uid(),hotel_id) LOOP n:=n+public.conc_boleto_auto_match_impl(h.hotel_id); END LOOP; RETURN n; END $$;